<!doctype html><html lang="sw"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>API Keys | Konekti Malipo</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;600;700;800&display=swap" rel="stylesheet"><style>body{margin:0;background:#f7f6ef;color:#10221d;font-family:Manrope,Arial}.shell{max-width:850px;margin:auto;padding:32px 24px}a{text-decoration:none;color:#147b67;font-weight:800}.top{display:flex;justify-content:space-between;align-items:center}.brand{color:#10221d;font-size:20px}.card{background:#fffefa;border:1px solid #dce5dc;border-radius:16px;padding:25px;margin-top:27px}h1{font-size:38px;letter-spacing:-1.8px;margin:33px 0 7px}.muted{color:#65766e;line-height:1.6}.field{display:grid;grid-template-columns:1fr auto;gap:12px;margin-top:20px}input{border:1px solid #cad7cc;border-radius:9px;padding:12px;font:14px Manrope}button{border:0;border-radius:999px;padding:12px 16px;background:#10221d;color:white;font-weight:800;cursor:pointer}.notice{background:#e4f2d8;color:#28583b;padding:14px;border-radius:10px;overflow-wrap:anywhere}.key{display:flex;justify-content:space-between;gap:16px;padding:16px 0;border-top:1px solid #dce5dc}.key small{color:#65766e;display:block;margin-top:3px}.revoke{background:transparent;color:#b24a3d;padding:0}@media(max-width:600px){.field{grid-template-columns:1fr}.key{align-items:flex-start;flex-direction:column}}</style></head><body><div class="shell"><div class="top"><a class="brand" href="{{ route('dashboard') }}">↗ Konekti Malipo</a><a href="{{ route('docs') }}">API docs</a></div><h1>API keys</h1><p class="muted">Tengeneza secret key kwa application yako. Key kamili itaonekana mara moja tu; ihifadhi kwenye server environment variable.</p><div class="card">@if(session('api_key_once'))<div class="notice"><b>Copy key yako sasa:</b><br><code>{{ session('api_key_once') }}</code></div>@endif<form method="post" action="{{ route('api-keys.store') }}">@csrf<div class="field"><input name="name" placeholder="Mfano: Production website" required><button>Create API key →</button></div></form></div><div class="card"><b>Active keys</b>@forelse($apiKeys as $apiKey)<div class="key"><span><b>{{ $apiKey->name }}</b><small>{{ $apiKey->prefix }}•••••• · Last used: {{ $apiKey->last_used_at?->diffForHumans() ?? 'Never' }}</small></span><form method="post" action="{{ route('api-keys.destroy', $apiKey) }}">@csrf @method('DELETE')<button class="revoke">Revoke</button></form></div>@empty<p class="muted">Bado hakuna API key.</p>@endforelse</div></div></body></html>
